#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }
    long long q;
    cin >> q;
    vector<vector<long long>> qs(q, vector<long long>(2));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> qs[i][j];
        }
    }

    vector<vector<int>> adj(n + 1);
    for (const vector<long long>& e : edges) {
        adj[e[0]].push_back((int)e[1]);
        adj[e[1]].push_back((int)e[0]);
    }
    vector<int> label(n + 1, 0);
    int count = 0;
    for (int start = 1; start <= n; start++) {
        if (label[start]) continue;
        count++;
        label[start] = count;
        vector<int> queue = {start};
        for (size_t i = 0; i < queue.size(); i++) {
            for (int w : adj[queue[i]]) {
                if (!label[w]) {
                    label[w] = count;
                    queue.push_back(w);
                }
            }
        }
    }
    for (const vector<long long>& query : qs) cout << (label[query[0]] == label[query[1]] ? "yes" : "no") << "\n";

    return 0;
}

