import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] edges = new long[(int) m][2];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }
        long q = Long.parseLong(next());
        long[][] qs = new long[(int) q][2];
        for (int i = 0; i < qs.length; i++) {
            for (int j = 0; j < qs[i].length; j++) {
                qs[i][j] = Long.parseLong(next());
            }
        }

        int nodes = (int) n;
        List<List<Integer>> adj = new ArrayList<>();
        for (int v = 0; v <= nodes; v++) adj.add(new ArrayList<>());
        for (long[] e : edges) {
            adj.get((int) e[0]).add((int) e[1]);
            adj.get((int) e[1]).add((int) e[0]);
        }
        int[] label = new int[nodes + 1];
        int count = 0;
        for (int start = 1; start <= nodes; start++) {
            if (label[start] != 0) continue;
            count++;
            label[start] = count;
            List<Integer> queue = new ArrayList<>();
            queue.add(start);
            for (int i = 0; i < queue.size(); i++) {
                for (int w : adj.get(queue.get(i))) {
                    if (label[w] == 0) {
                        label[w] = count;
                        queue.add(w);
                    }
                }
            }
        }
        StringBuilder out = new StringBuilder();
        for (long[] query : qs) out.append(label[(int) query[0]] == label[(int) query[1]] ? "yes" : "no").append("\n");
        System.out.print(out);
    }
}
